"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { Flex, Text } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { useMarketContext } from "../../ContextProvider";
import GridItem from "../GridItem";
import { formatUnits } from "viem";
import { formatPriceWithSignificantDigits } from "../../utils/healthFactorUtils";
const TokenInfoPrice = ({
  tokenSymbol,
  tokenAddress,
  priceUsd,
  chainId
}) => {
  return <Flex row alignItems="center" gap={"$gap8"}>
      <PortfolioLogo
    chainId={chainId}
    tokenSymbol={tokenSymbol}
    images={[getTokenLogoUrl(tokenAddress)]}
    size={18}
  />
      <Text variant="body2" $sm={{ variant: "body3" }} color="$neutral1">
        {tokenSymbol}
      </Text>
    </Flex>;
};
function formatOraclePrice(oraclePrice, collateralSymbol, loanSymbol, collateralDecimals, loanDecimals) {
  if (oraclePrice === 0n) return "-";
  const exponent = 36 - collateralDecimals + loanDecimals;
  const priceValue = Number(formatUnits(oraclePrice, exponent));
  return `1 ${collateralSymbol} = ${formatPriceWithSignificantDigits(priceValue)} ${loanSymbol}`;
}
export default function MarketAttributes() {
  const { marketData, chainId } = useMarketContext();
  if (!marketData) {
    return null;
  }
  return <Flex mt={"$spacing36"}>
      <Text variant="subheading1">Market Attributes</Text>
      <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "1fr 1fr" }}
    $lg={{ gridTemplateColumns: "1fr" }}
    gap="$gap24"
    mt={"$spacing8"}
  >
        <Flex className="left-items">
          <GridItem
    label="Collateral"
    component={<TokenInfoPrice
      tokenSymbol={marketData.collateralToken.symbol}
      tokenAddress={marketData.collateralToken.address}
      priceUsd={marketData.collateralPriceUsd}
      chainId={chainId}
    />}
    copyable
  />
          <GridItem
    label="Loan"
    component={<TokenInfoPrice
      tokenSymbol={marketData.loanToken.symbol}
      tokenAddress={marketData.loanToken.address}
      priceUsd={marketData.loanPriceUsd}
      chainId={chainId}
    />}
    copyable
  />
          <GridItem label="Liquidation LTV" value={`${marketData.lltvPercent}%`} />
        </Flex>

        <Flex className="right-items">
          <GridItem
    label="Oracle price"
    value={formatOraclePrice(
      marketData.oraclePrice,
      marketData.collateralToken.symbol,
      marketData.loanToken.symbol,
      marketData.collateralToken.decimals,
      marketData.loanToken.decimals
    )}
  />
          <GridItem label="Borrow Rate" value={`${marketData.borrowRate.toFixed(2)}%`} />
          <GridItem label="Utilization" value={`${marketData.utilizationRate.toFixed(1)}%`} />
        </Flex>
      </Flex>
    </Flex>;
}
